INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷79·晋高祖纪·天福五年五月至六月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c41515820cdf0fa2e63ec5eb0e14bf77c385f320/content/books/zizhi-tongjian/vol-282/year-0940/part-02/sources/library/jiuwudaishi-079-anyuan-campaign/source.txt", "note": "《旧五代史》卷79·晋高祖纪·天福五年五月至六月，段落 jiu-wudaishi-205deb4a7860-p001946；已核上下文及传主，纸本及异文待核。", "id": "a051c129-970c-5e21-a2a0-e410299fcb29"}, {"title": "资治通鉴·卷282·天福五年夏秋", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c41515820cdf0fa2e63ec5eb0e14bf77c385f320/content/books/zizhi-tongjian/vol-282/year-0940/part-02/sources/library/tongjian-282-940-summer/source.txt", "note": "《资治通鉴》卷282·天福五年夏秋，段落 zizhi-tongjian-a63549944a71-p003353；已核上下文及传主，纸本及异文待核。", "id": "908167a1-4c93-544d-8f5a-8739bae0d275"}, {"title": "新五代史·卷8·晋本纪·天福五年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c41515820cdf0fa2e63ec5eb0e14bf77c385f320/content/books/zizhi-tongjian/vol-282/year-0940/part-02/sources/library/xinwudaishi-008-tianfu-five/source.txt", "note": "《新五代史》卷8·晋本纪·天福五年，段落 xin-wudaishi-b08f244b9241-p000318；已核上下文及传主，纸本及异文待核。", "id": "a628ad85-ffb6-5417-b386-72e51e501435"}, {"title": "新五代史·卷47·马全节传·安州战事", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c41515820cdf0fa2e63ec5eb0e14bf77c385f320/content/books/zizhi-tongjian/vol-282/year-0940/part-02/sources/library/xinwudaishi-047-ma-quanjie-anyuan/source.txt", "note": "《新五代史》卷47·马全节传·安州战事，段落 xin-wudaishi-b08f244b9241-p001811；已核上下文及传主，纸本及异文待核。", "id": "6c456d35-6233-5878-98ff-cc4ed7536e2a"}, {"title": "资治通鉴·卷282·天福五年春夏", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c30e8592e48c53567d2d07454baccf80e3e0ec55/content/books/zizhi-tongjian/vol-282/year-0940/part-01/sources/library/tongjian-282-940-spring/source.txt", "note": "《资治通鉴》卷282·天福五年春夏，段落 zizhi-tongjian-a63549944a71-p003352；已核上下文及传主，纸本及异文待核。", "id": "f1900b5e-ea31-5aca-8cf7-9f5082103413"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "钱弘僔", "aliases": ["弘僔"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越王钱元瓘的儿子。937年四月被立为世子。", "biography": null, "status": "draft", "id": "b277fec5-6d3f-50f1-9151-ce20879f41b3"}, {"name": "仰仁诠", "aliases": ["仰仁詮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：仰仁诠，受遣牙将。", "biography": null, "status": "draft", "id": "bb229efa-8831-569a-84b2-c48d86bee7a7"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}, {"name": "王延羲", "aliases": ["王曦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国宗室，王继鹏的叔父，曾任左仆射、同平章事。939年被政变军队拥立，自称威武节度使、闽国王，更名王曦，改元永隆。生卒年暂未核实。", "biography": null, "status": "draft", "id": "e706d6ae-56f4-5e44-9d24-f3060ae87cbb"}, {"name": "王继业", "aliases": ["王繼業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国前汀州刺史。939年受王延羲派遣追赶王继鹏，随后将王继鹏带回并杀死。《资治通鉴》称他为王延羲兄长的儿子，《新五代史》称为王延羲之子，亲属异说暂未裁定。生卒年未载。", "biography": null, "status": "draft", "id": "ba45fd2b-6648-5c10-aed8-a06182d774d7"}, {"name": "胡汉筠", "aliases": ["胡漢筠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李金全的亲近吏员。受任中门使，掌管安远军府事务。史书记载他遭朝廷召调后劝李金全背离朝廷，又谋害反对自己的庞令图和接替他的贾仁沼。各次行动的具体日期并非全都记明。", "biography": null, "status": "draft", "id": "671f993a-ecbf-5fc0-8a33-2dfa8daa2b04"}, {"name": "李金全", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李金全，前节度使、多次献马者。", "biography": null, "status": "draft", "id": "13205047-3c88-59d8-9900-ef435bd6e59a"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "马全节", "aliases": ["馬全節"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马全节，金州防御使、以私财给军并拒战者。", "biography": null, "status": "draft", "id": "bb5608d9-eabe-58ce-8c56-b07e57faadb5"}, {"name": "安审晖", "aliases": ["安審暉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安审琦的兄长。940年任保大节度使，受命副马全节讨李金全，追击南唐军，黄花谷、云梦战事获胜。《新五代史》《旧五代史》写安審暉，展示使用简体。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "9e82b7a2-6a78-5042-8d8a-b030debbc67f"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "安审琦", "aliases": ["安審琦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安审琦，彰圣都指挥使、领顺化节度使者。", "biography": null, "status": "draft", "id": "a579a6a1-65a5-5c8a-9c6c-be178cb049aa"}, {"name": "张纬（李金全推官）", "aliases": ["张纬", "張緯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李金全属下推官。史书记载他与胡汉筠互相勾结，以奉承的方式影响李金全，具体起止时间未载。", "biography": null, "status": "draft", "id": "804e88ac-166b-5b44-9fc8-a1db17078f27"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "李承裕", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 940, "description": "南唐鄂州屯营使。940年与段处恭奉命迎接李金全，随后据安州，与后晋军交战战败被俘，遭马全节杀死。遇害地点、顺序和原因各书记载有异。出生年未载。", "biography": null, "status": "draft", "id": "940c9b4c-bdfa-56b8-b1ba-877208141731"}, {"name": "段处恭", "aliases": ["段處恭"], "era": "五代十国", "birth_year": null, "death_year": 940, "description": "南唐将领。940年与李承裕奉命迎接李金全，在黄花谷被后晋追兵击败时战死。出生年未载。", "biography": null, "status": "draft", "id": "2bfd9e28-d351-5225-a2ee-074b28752aad"}, {"name": "尚全恭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐客省使。940年受李昪派遣，前往闽国调解王延羲、王延政兄弟的争端。生卒年未载。", "biography": null, "status": "draft", "id": "6452626b-cdbf-50d5-972c-9d2e44e338bc"}, {"name": "张建崇", "aliases": ["張建崇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领。940年安州战事中据云梦桥抵抗后晋军，使安审晖停止追击返回。生卒年未载。", "biography": null, "status": "draft", "id": "a6d5b9a5-f56c-53b6-b3e6-ef6b9cb221c0"}, {"name": "杜光业", "aliases": ["杜光業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐监军。940年安州战败后，与其他被俘者被送到大梁；石敬瑭遣返，李昪拒绝接收，后来被后晋授官。《旧五代史》在相关记载中写杜光鄴，字形待核。生卒年未载。", "biography": null, "status": "draft", "id": "c8e5e97f-ce88-5eb4-8c75-bc67b8a40040"}, {"name": "祖全恩", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领。李昪命他带兵迎接逃往吴国的卢文进，并告诫在城外接应、不得抢掠。本处是回述此前经历，具体日期未载。生卒年未载。", "biography": null, "status": "draft", "id": "9e06353a-5151-57d8-9194-a100cc1ce8eb"}, {"name": "卢文进", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：卢文进。", "biography": null, "status": "draft", "id": "ead2e914-83dd-5f41-bf9a-5956fbd149ab"}, {"name": "刘康（后晋将领）", "aliases": ["刘康", "劉康"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋旧将。940年石敬瑭将被南唐拒收的士卒编为显义都，命刘康统领。生卒年未载。", "biography": null, "status": "draft", "id": "492fbe39-0864-51fe-a95e-73ebeea2c8ea"}, {"name": "郑元弼", "aliases": ["鄭元弼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国礼部员外郎。939年奉王继恭的表章，随卢损前往后晋进贡。生卒年未载。", "biography": null, "status": "draft", "id": "a656f099-5f42-574b-bfa0-daa89cb73913"}, {"name": "桑千", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 940, "description": "安州马步副都指挥使。940年因不跟随李金全拒命而死，七月获后晋朝廷追赠官职。出生年未载。", "biography": null, "status": "draft", "id": "d6fd3e50-0450-5237-8b3b-2b1727e783f2"}, {"name": "王万金", "aliases": ["王萬金"], "era": "五代十国", "birth_year": null, "death_year": 940, "description": "安州威和指挥使。940年因不跟随李金全拒命而死，七月获后晋朝廷追赠官职。出生年未载。", "biography": null, "status": "draft", "id": "7a266ce5-0b29-5fdf-8938-ab1cdf218e16"}, {"name": "成彦温", "aliases": ["成彥溫"], "era": "五代十国", "birth_year": null, "death_year": 940, "description": "安州威和指挥使。940年因不跟随李金全拒命而死，七月获后晋朝廷追赠官职。出生年未载。", "biography": null, "status": "draft", "id": "753e24a7-1663-5d6e-b13e-0657d8ec9de6"}, {"name": "庞守荣", "aliases": ["龐守榮"], "era": "五代十国", "birth_year": null, "death_year": 940, "description": "安州马步都指挥使。李金全拒命时，讥笑不肯从叛而死的桑千等，以迎合李金全。940年七月被石敬瑭派人处死。出生年未载。", "biography": null, "status": "draft", "id": "b82d1e6c-4268-5198-bb7e-a3e8f6d329e7"}, {"name": "贾仁沼", "aliases": ["賈仁沼", "贾仁绍", "賈仁紹"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋吏员。石敬瑭派他接替胡汉筠，后来被胡汉筠毒杀。具体死亡年份此段未载。", "biography": null, "status": "draft", "id": "90f17e0d-51f1-5fdf-a633-c2210c39d294"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "吴越世子钱弘僔去世", "start_year": 940, "end_year": 940, "time_original": "940年四月甲子", "dynasty": "五代十国", "description": "吴越世子钱弘僔去世。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "15419137-e033-55e5-b2f2-9317ef0e9b29"}, {"title": "吴越援军抵达后，王延政送牛酒慰劳，请求撤军", "start_year": 940, "end_year": 940, "time_original": "940年四月条下，具体日期未载", "dynasty": "五代十国", "description": "仰仁诠等率吴越军到达建州。王延政说福州军已经败退，送牛酒慰劳，并请求吴越军撤回。", "phases": [], "location_name": "建州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d657164c-9caa-5967-8fbf-296ac584fa84"}, {"title": "仰仁诠等拒绝撤军，在建州西北设营", "start_year": 940, "end_year": 940, "time_original": "940年四月条下，具体日期未载", "dynasty": "五代十国", "description": "仰仁诠等拒绝撤军，在建州西北设营。", "phases": [], "location_name": "建州西北", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d85dc487-2dc1-5724-9f90-83e56eb38737"}, {"title": "王延政因惧怕吴越援军，转向王延羲求援", "start_year": 940, "end_year": 940, "time_original": "940年四月条下，具体日期未载", "dynasty": "五代十国", "description": "王延政因惧怕吴越援军，转向王延羲求援。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d7cc6aad-22b6-57e0-9c43-ab914ef51c9c"}, {"title": "王延羲派王继业率两万兵救援王延政", "start_year": 940, "end_year": 940, "time_original": "940年四月条下，具体日期未载", "dynasty": "五代十国", "description": "王延羲派王继业率两万兵救援王延政。", "phases": [], "location_name": "建州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "1b0d7e79-49be-5168-afc1-55c33c94c94d"}, {"title": "王延羲写信责问吴越，并派轻兵截断吴越粮道", "start_year": 940, "end_year": 940, "time_original": "940年四月条下，具体日期未载", "dynasty": "五代十国", "description": "王延羲写信责问吴越，并派轻兵截断吴越粮道。", "phases": [], "location_name": "吴越军粮道", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2464b747-aa0d-5763-9d63-1406a4e138fb"}, {"title": "长时间下雨，吴越军粮食耗尽", "start_year": 940, "end_year": 940, "time_original": "940年四月条下，具体日期未载", "dynasty": "五代十国", "description": "《资治通鉴》记，当时长时间下雨，吴越军的粮食耗尽。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "7c1b97b4-7e28-565d-a05a-812c6095637b"}, {"title": "王延政出兵大败吴越军，俘虏与斩杀人数以万计", "start_year": 940, "end_year": 940, "time_original": "940年五月，具体日期未载", "dynasty": "五代十国", "description": "王延政出兵大败吴越军，俘虏与斩杀人数以万计。", "phases": [], "location_name": "建州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "62ea8a1b-73d3-5267-9e6c-192dc1d9d470"}, {"title": "仰仁诠等撤离建州", "start_year": 940, "end_year": 940, "time_original": "940年五月癸未", "dynasty": "五代十国", "description": "《资治通鉴》记，癸未，仰仁诠等撤离建州。电子底本写作仁诠等诠遁，重复字形保留在原文。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "5fd40bab-25f0-5eb2-8f35-98e969dbb797"}, {"title": "胡汉筠听说贾仁沼的